function editorChanged(){return !!ui.editor&&(!same(saved,drafts)||newNetworkIp!==ui.editor.baseIp||!selectedConfiguration||!!ui.editor.id&&row(ui.editor.id)?.configurationId!==selectedConfiguration||configurationName.trim()!==baseConfigurationName);}
async function closeEditor(){if(!ui.editor||ui.editor.saving)return;if(!ui.editor.readOnly&&editorChanged()&&!await confirmAction('放弃未保存的设置？','已保存设置保持不变。','放弃修改'))return;if(!ui.editor.readOnly){configurationDrafts.delete(selectedConfiguration||'new');newNetworkIp=ui.editor.baseIp;drafts=clone(saved);configurationName=baseConfigurationName;}$('network-dialog').close();ui.editor=null;render();}
async function saveEditor(){
 if(!ui.editor||ui.editor.readOnly)return;
 for(const key of configurationGroups){const error=validateSection(key);if(error){section=key;renderEditor();$('settings-error').textContent=error;return;}}
 if(!ui.editor.id&&newNetworkIp.trim()){
  const ip=newNetworkIp.trim().split('.').map(Number),valid=ip.length===4&&ip.every(v=>Number.isInteger(v)&&v>=0&&v<=255)&&ip[3]>0&&ip[3]<255&&(ip[0]===10||ip[0]===172&&ip[1]>=16&&ip[1]<=31||ip[0]===192&&ip[1]===168);
  if(!/^(\d{1,3}\.){3}\d{1,3}$/.test(newNetworkIp.trim())||!valid){section='virtual';renderEditor();$('settings-error').textContent='请填写有效的私有 IPv4，或留空自动分配。';return;}
 }
 const target=row(ui.editor.id),assign=!!target&&target.configurationId!==selectedConfiguration,write=!selectedConfiguration||!same(saved,drafts)||configurationName.trim()!==baseConfigurationName,uses=write?configuration()?.networks||[]:[],affected=[...new Set(uses.map(n=>n.name).concat(assign?[target.name]:[]))];
 if(affected.length&&!await confirmAction('保存并应用网络设置？','将更新：'+affected.join('、')+'。需要时会重新连接。','保存并应用'))return;
 ui.editor.saving=true;
 try{
  const previous=selectedConfiguration||'new';
  if(write){const reply=await command('configuration',{networkId:'',configuration:{action:'save',id:selectedConfiguration,name:configurationName.trim()||newNetworkName||'网络设置',expectedRevision:configurationRevision,settings:settingsDto(),confirmReconnect:true}});selectedConfiguration=reply.configurationId||selectedConfiguration;configurationRevision=configuration()?.revision||1;saved=clone(drafts);baseConfigurationName=configurationName;}
  if(target&&target.configurationId!==selectedConfiguration)await command('configuration',{networkId:target.id,configuration:{action:'assign',id:selectedConfiguration,expectedRevision:configurationRevision,confirmReconnect:true}});
  if(!ui.editor.id){ui.newConfig=selectedConfiguration;try{localStorage.setItem('conwu-create-ip-draft',newNetworkIp.trim());}catch{}}
  configurationDrafts.delete(previous);configurationDrafts.delete(selectedConfiguration);$('network-dialog').close();ui.editor=null;settingsHydrated=false;render();notify('网络设置已保存');
 }finally{if(ui.editor)ui.editor.saving=false;controls();}
}
async function create(){if(!newNetworkName.trim())throw Error('请为网络起一个名称。');const c=workspaceState.configurations.find(c=>c.id===ui.newConfig);if(!c){openEditor();return;}let p=c.settings;if(!p.service&&!p.directMode&&ui.coord?.discover&&ui.coord.server&&!c.networks.length){const updated={...p,service:ui.coord.server};await command('configuration',{networkId:'',configuration:{action:'save',id:c.id,name:c.name,expectedRevision:c.revision,settings:updated}});p=updated;}if(p.connectionSource==='existing'&&!p.existingEntries.some(e=>e.peerSlot===0))throw Error('请在网络设置中填写本机已有入口。');selectedConfiguration=c.id;newNetworkIp=newNetworkIp.trim();const reply=await command('network',{networkId:'',network:{action:p.directMode?'create-direct':'create',configurationId:c.id,service:p.service,certificatePin:p.certificatePin,mode:p.pathSelection==='udp-only'?'udp':'faketcp',name:newNetworkName.trim(),requestedVirtualIp:newNetworkIp,expectedNetwork:''}});ui.hostId=reply.status?.selectedNetworkId||selectedNetwork;render();notify('网络已创建');}
function lookupKind(){const kind=$('lookup-kind').value;$('lookup-address-label').textContent=kind==='entry'?'目标主机的可达入口':'HTTPS 协调地址';$('lookup-address').value=ui.lookup?.kind===kind?ui.lookup.address:kind==='coordinator'?ui.coord?.server||'':'';$('lookup-address').placeholder=kind==='entry'?'IP:端口 或 HTTPS/TXT 等订阅链接':'https://coord.example.com/';}
function openLookup(){const kind=ui.lookup?.address?ui.lookup.kind:'entry';$('lookup-kind').value=kind;lookupKind();$('lookup-error').textContent='';$('lookup-dialog').showModal();}
async function join(){const invite=ui.joinKind==='invite',code=(invite?joinInviteValue:joinCodeValue).replace(/\s/g,'');if(invite?!code.startsWith('SL6.'):!/^\d{6}$/.test(code))throw Error(invite?'请粘贴主机生成的完整 SL6. 直连邀请。':'请输入完整的六位配对码。');if(!invite&&!ui.lookup?.address){openLookup();return;}const action=invite?'join-invitation':ui.lookup.kind==='entry'?'join-direct-short':'join';const reply=await command('network',{networkId:'',network:{action,autoConfigure:true,code,entry:ui.lookup?.kind==='entry'?ui.lookup.address:'',service:action==='join'?ui.lookup.address:'',mode:'faketcp',name:'连接 '+(all().length+1),expectedNetwork:''}});ui.joinId=reply.status?.selectedNetworkId||selectedNetwork;render();notify('申请已发送，等待主机批准');}
bindJoinInput=function(){const input=$('join-code');if(input)input.oninput=()=>{joinCodeValue=input.value.replace(/\D/g,'').slice(0,6);input.value=joinCodeValue;input.closest('.digits-input').querySelectorAll('.digit').forEach((e,i)=>{e.textContent=joinCodeValue[i]||'';e.classList.toggle('filled',!!joinCodeValue[i]);});joinError='';$('join-error').textContent='';};if($('join-invite'))$('join-invite').oninput=e=>joinInviteValue=e.target.value;if($('join-form'))$('join-form').onsubmit=e=>{e.preventDefault();void run(join).catch(()=>{});};};
async function removeNetwork(id,confirmed=false){const n=row(id);if(!n)return;const host=n.status.isOwner;if(!confirmed&&!await confirmAction(host?'删除本机创建的网络？':'删除本机的网络记录？',host?'结束“'+n.name+'”并删除此网络。其他网络和本机设置保留。':'本机退出“'+n.name+'”并删除本机记录，不会删除主机的网络。','确认删除','danger'))return;try{await command('network',{networkId:id,network:{action:host?'delete-network':'leave',expectedNetwork:n.status.networkId,confirmReplace:true}});}catch(error){if(!row(id))return;if(!await confirmAction('远端尚未确认','可以只移除本机记录，不代表远端授权已经撤销。原因：'+error.message,'仅从本机移除','danger'))return;await command('network',{networkId:id,network:{action:n.status.networkId?'forget-network':'remove-network',expectedNetwork:n.status.networkId,confirmReplace:true}});}if(ui.hostId===id)ui.hostId='';if(ui.joinId===id)ui.joinId='';render();notify('本机网络已移除，其他网络和设置保留');}
