async function lockedSave(key,action){if(ui[key])return;ui[key]=true;controls();try{return await action();}finally{ui[key]=false;controls();}}
async function saveDevice(){const d=ui.device;if(!d.name.trim())throw Error('请输入设备名称。');const action={action:'settings',settings:deviceSettings(),expectedRevision:ui.deviceRevision,confirmReplace:true,patch:{deviceName:d.name.trim(),expectedDeviceName:ui.deviceBase.name,logLevel:d.level,expectedLogLevel:ui.deviceBase.level}};if(d.startup!==ui.deviceBase.startup){action.autoStart=d.startup;action.expectedAutoStart=ui.deviceBase.startup;}await command('save-settings',{networkId:'',settingsBatch:{device:action,networks:[]}});terminalTheme=d.terminal;try{localStorage.setItem('streamlink-terminal-theme',terminalTheme);}catch{}ui.deviceBase=deviceValue();ui.device=clone(ui.deviceBase);ui.deviceRevision=workspaceState.deviceSettingsRevision;render();notify('本机设置已保存');}
