async function generateFor(id){const n=row(id),s=n.status,short=s.networkDirect&&s.settings.connectionSource==='existing'&&ui.hostKinds.get(id)!=='invite';if(s.pairing?.candidate&&!await confirmAction('重新生成邀请？','当前尚未处理的申请将被取消。','重新生成'))return;await command('network',{networkId:id,network:{action:short?'invite-short':'invite',expectedNetwork:s.networkId}});render();notify(short?'配对码已生成':'邀请已生成');}
