document.addEventListener('input',e=>{const el=e.target,scope=el.dataset.uiScope,key=el.dataset.uiKey;if(scope&&key){if(scope==='host')ui.coord.host[key]=el.type==='checkbox'?el.checked:el.value;else ui[scope][key]=el.type==='checkbox'?el.checked:el.value;controls();}if(el.id==='new-network-ip'){newNetworkIp=el.value;controls();}});
